    for (int start = 1; start <= N; start++) {
        if (vis[start]) continue;

        int len = 0;
        int x = start;
        while (!vis[x]) {
            vis[x] = 1;
            cycle[len++] = x;
            x = r[x];
        }

        ll mod = len;

        /* Fast doubling Fibonacci modulo mod:
