vector<int> compose(const vector<int>& p, const vector<int>& q) {
    // f(p, q) = q ∘ p^{-1}
    // result[p[i]] = q[i]
    int n = (int)p.size() - 1;
    vector<int> r(n + 1);
    for (int i = 1; i <= n; ++i) r[p[i]] = q[i];
    return r;
}

vector<int> inverse_perm(const vector<int>& p) {
    int n = (int)p.size() - 1;
    vector<int> inv(n + 1);
    for (int i = 1; i <= n; ++i) inv[p[i]] = i;
    return inv;
}

vector<int> multiply(const vector<int>& a, const vector<int>& b) {
    // a ∘ b : apply b first, then a
    int n = (int)a.size() - 1;
    vector<int> r(n + 1);
    for (int i = 1; i <= n; ++i) r[i] = a[b[i]];
    return r;
}

vector<int> power_perm(vector<int> base, long long exp) {
    int n = (int)base.size() - 1;
    vector<int> res(n + 1);
    for (int i = 1; i <= n; ++i) res[i] = i;
    while (exp > 0) {
        if (exp & 1) res = multiply(base, res);
        base = multiply(base, base);
        exp >>= 1;
    }
    return res;
}

