            cout << q[i];
        }
        cout << '\n';
        return 0;
    }

    // Let b_n = a_n^{-1}.
    // Since a_{n+2} = a_{n+1} ∘ a_n^{-1},
    // we get b_{n+2} = b_n ∘ b_{n+1}.
    //
    // Define r = p^{-1} ∘ q.
    // Then one can derive:
    // b_n = p^{-1} ∘ r^{F_n}, where F_1 = 0, F_2 = 1, F_{n+2} = F_n + F_{n+1}.
    // Hence:
    // a_n = (r^{F_n})^{-1} ∘ p = r^{-F_n} ∘ p.
    //
    // Since r^6 = identity for this recurrence structure on permutations,
    // exponents are needed only modulo 6.
    //
    // Fibonacci modulo 6 has period 24.

    vector<int> pinv = inverse_perm(p);
    vector<int> r = multiply(pinv, q); // r = p^{-1} ∘ q

    // Compute F_K modulo 6, with F_1=0, F_2=1
    int fk_mod6;
    if (K == 1) fk_mod6 = 0;
    else if (K == 2) fk_mod6 = 1;
    else {
        int a = 0, b = 1;
        for (long long i = 3; i <= K; ++i) {
            int c = (a + b) % 6;
            a = b;
            b = c;
            if (i > 100) break;
        }
        // Better using period 24
        long long kk = (K - 1) % 24 + 1;
        if (kk == 1) fk_mod6 = 0;
        else if (kk == 2) fk_mod6 = 1;
        else {
            int x = 0, y = 1;
            for (int i = 3; i <= kk; ++i) {
                int z = (x + y) % 6;
                x = y;
                y = z;
            }
            fk_mod6 = y;
        }
    }

    // Need r^{-F_K} = r^(6 - F_K mod 6) mod 6
    int exp = (6 - fk_mod6) % 6;
    vector<int> re = power_perm(r, exp);
    vector<int> ans = multiply(re, p);

    for (int i = 1; i <= N; ++i) {
        if (i > 1) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';

    return 0;
