def compose(a, b):
    # returns a∘b: (a∘b)[i] = a[b[i]]
    return [a[b[i]-1] for i in range(N)]

def inverse(a):
    inv = [0]*N
    for i, val in enumerate(a):
        inv[val-1] = i+1
    return inv

def T(state):
    x, y = state
    # returns (y, compose(y, inverse(x)))
    return (y, compose(y, inverse(x)))

def apply_power(Tfunc, k, state):
    # apply Tfunc k times to state using binary exponentiation on transformations
    # Represent transformation as a function
    while k > 0:
        if k & 1:
            state = Tfunc(state)
        # Double the transformation
        Tfunc = lambda s, f=Tfunc: f(f(s))
        k >>= 1
    return state
